package com.meenai.mina.core.model

interface ChatModel {
    val capabilities: Capabilities

    /** Model name, only used for recording. */
    val name: String get() = ""

    /** Throw [ModelError] on failure. */
    suspend fun complete(system: String, messages: List<Message>, tools: List<ToolSpec>): ModelReply
}

/** Supports paragraph-by-paragraph model; implementations that do not support continue to use [ChatModel.complete]. */
interface StreamingChatModel : ChatModel {
    /** [onText] received the full visible text generated by this request; it does not include model private thoughts or tool parameters. */
    suspend fun completeStreaming(
        system: String, messages: List<Message>, tools: List<ToolSpec>, onText: (String) -> Unit,
    ): ModelReply
}
